  let resizeTimer,reviewLastWidth=-1;new ResizeObserver(entries=>{const width=entries[0].contentRect.width;if(Math.abs(width-reviewLastWidth)<1)return;reviewLastWidth=width;clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(view==='path')renderPath();else renderOverview()},80)}).observe($('graph-wrap'));
// Transform recorded outcomes, not tool names alone, into a small branch vocabulary.
function collectToolResults(session, facts, fileOperations) {
  const covered = new Set();
  const results = session.overview.episodes.map(e => {
    const seqs = [...e.failureSeqs, ...e.readSeqs, ...e.pairs.map(p => p.successSeq)];
    seqs.forEach(seq => covered.add(seq));
    return { id: 'incident:' + e.id, kind: 'incident', turn: e.turn, step: e.steps?.[0], time: e.firstError, seqs, incident: e, calls: [] };
  });
  const files = new Map();
  for (const op of fileOperations) { if (!files.has(op.seq)) files.set(op.seq, []); files.get(op.seq).push(op); }
  for (const t of session.turns) for (const step of t.steps) {
    const groups = new Map();
    for (const call of step.calls) {
      if (covered.has(call.seq)) continue;
      const fact = facts[call.seq], records = files.get(call.seq) || [], file = records[0], operation = fact?.operation;
      let kind = null;
      if (call.status === 'error' || fact?.tone === 'bad') kind = 'error';
      else if (call.status !== 'returned' || call.resultSeq == null) { if (operation) kind = 'pending'; else continue; }
      else if (operation) kind = ({ write: 'change', search: 'query' })[operation.family] || operation.family;
      else if (/^命令输出报告：(?:PASS|FAIL|Tests? (?:passed|failed)|Test Files)\b/i.test(fact?.outcome || '')) kind = 'check';
      else if (file?.kind === 'change') kind = 'change';
      else if (file?.kind === 'read') kind = 'read';
      else if (/^(?:trajectory|session|session_event)_(?:read|search)$/.test(call.name) && /(?:返回|命中) \d+ 条/.test(fact?.outcome || '')) kind = 'query';
      else if (['grep', 'glob', 'web_search', 'web_fetch'].includes(call.name) && fact?.outcome && !/已收到工具返回|工具已返回/.test(fact.outcome)) kind = 'query';
      if (!kind) continue;
      const key = operation ? call.name + ':' + kind : kind;
      let group = groups.get(key);
      if (!group) { group = { id: t.number + ':' + step.number + ':' + key, kind, family: operation?.family, recorded: !!operation, turn: t.number, step: step.number, time: call.end ?? call.start, seqs: [], calls: [] }; groups.set(key, group); }
      group.seqs.push(call.seq);
      group.calls.push({ ...call, file: file?.path ?? null, files: records, fact });
      group.time = Math.max(group.time, call.end ?? call.start);
    }
    results.push(...groups.values());
  }
  return results.sort((a, b) => a.time - b.time || a.id.localeCompare(b.id));
}

function toolResultLabel(result) {
  if (result.kind === 'incident') return null;
  const calls = result.calls, paths = [...new Set(calls.map(c => c.file).filter(Boolean))];
  if (result.recorded) {
    const call = calls[0], operation = call.fact?.operation;
    if (result.kind === 'pending') return call.name + (calls.length > 1 ? ' ×' + calls.length : '') + ' · 待返回';
    if (result.kind === 'error') return call.name + ' · 受阻';
    if (calls.length > 1) return call.name + ' ×' + calls.length;
    if (call.name === 'grep') return 'grep · ' + (operation?.search?.total ?? operation?.search?.shown ?? '?') + ' 处匹配';
    if (call.name === 'glob') return 'glob · 发现路径';
    if (operation?.family === 'read') return 'read · ' + (operation.metrics.find(([key]) => key === '返回行数')?.[1] || '取回内容');
    if (operation?.family === 'write') return call.name + ' · ' + (paths[0]?.split(/[\\/]/).at(-1) || '文件修改');
    if (operation?.family === 'command') {
      const program = operation.subject.match(/\b(?:node|python3?|lean|lake|git|rg|pnpm|npm|Get-Content|Select-String)\b/)?.[0];
      return call.name + ' · ' + (program || '命令输出');
    }
    return call.name + ' · ' + ({ process: '后台输出', web: '网页返回', coordination: '协作返回' }[operation?.family] || '工具返回');
  }
  if (result.kind === 'error') return calls.length > 1 ? calls.length + ' 次受阻' : '操作受阻';
  if (result.kind === 'read') {
    const range = calls.length === 1 && calls[0].fact?.outcome?.match(/返回第 (\d+)–(\d+) 行/);
    return range ? '取回 ' + (Number(range[2]) - Number(range[1]) + 1) + ' 行' : paths.length === 1 ? '取回文件内容' : '取回 ' + paths.length + ' 个文件';
  }
  if (result.kind === 'change') {
    const preview = calls.length === 1 && calls[0].fact?.preview;
    if (preview && !preview.partial && preview.before === '' && (calls[0].nativeName === 'write' || calls[0].name === 'write')) return '写入 ' + preview.after.split(/\r?\n/).length + ' 行';
    return preview && !preview.partial ? '替换 ' + preview.before.split(/\r?\n/).length + '→' + preview.after.split(/\r?\n/).length + ' 行' : paths.length > 1 ? '修改 ' + paths.length + ' 个文件' : '写入修改已返回';
  }
  if (result.kind === 'check') {
    if (calls.some(c => /^命令输出报告：FAIL\b/i.test(c.fact?.outcome || '') || /^\s*FAIL\b/im.test(c.result?.text || ''))) return '检查报告未过';
    if (calls.every(c => /^命令输出报告：PASS\b/i.test(c.fact?.outcome || ''))) return '检查有通过项';
    return '取得检查输出';
  }
  if (calls.length === 1) {
    const outcome = calls[0].fact?.outcome || '';
    if (/^(?:返回|命中) 0 条/.test(outcome)) return '没有匹配结果';
    return outcome.match(/(?:返回|命中) \d+ 条(?:事件记录|记录)?/)?.[0] || '取回查询结果';
  }
  return calls.length + ' 项查询结果';
}

function compactToolLabel(call) {
  const operation = call.fact?.operation;
  if (call.name === 'grep') return 'grep ' + (operation?.search?.total ?? operation?.search?.shown ?? '?') + '处';
  if (operation?.family === 'read') return 'read ' + (operation.metrics.find(([key]) => key === '返回行数')?.[1] || '内容').replace(/\s+/g, '');
  if (operation?.family === 'command') { const program = operation.subject.match(/\b(?:node|python3?|lean|lake|git|rg|pnpm|npm)\b/)?.[0]; return program ? call.name + '/' + program : call.name; }
  return call.name === 'job_output' ? '后台输出' : call.name;
}

function toolResultEndpoint(members) {
  const priority = result => result.kind === 'error' || result.kind === 'incident' && !result.incident.complete ? 3 : result.kind === 'pending' ? 2 : 1;
  return members.reduce((chosen, member) => priority(member.result) > priority(chosen) ? member.result : chosen, members[0].result);
}

// Native measurements are kept intact. Inconsistent historical timing is not drawn as a ratio.
function toolTiming(stats, step) {
  if (!stats || !Number.isFinite(stats.toolWall)) return { status: 'missing', spans: [], coverage: null, cumulative: null };
  const wall = step.end - step.start;
  const candidates = stats.calls.filter(c => Number.isFinite(c.startedAt) && Number.isFinite(c.endedAt));
  const valid = wall >= 0 && stats.toolWall >= 0 && stats.toolWall <= wall + 1 && candidates.every(c => c.startedAt >= step.start && c.endedAt >= c.startedAt && c.endedAt <= step.end + 1);
  return { status: valid ? 'measured' : 'inconsistent', coverage: stats.toolWall, cumulative: stats.tool,
    spans: valid ? candidates.map(c => ({ start: c.startedAt, end: c.endedAt, seq: c.seq })) : [],
    pending: stats.toolPending, partial: stats.tools.reduce((sum, tool) => sum + tool.count, 0) > stats.calls.length };
}

// Presentation arithmetic only. Occupancy and source estimates stay separate.
function contextOverview(pressure, breakdown, composition) {
  const valid = value => typeof value === 'number' && Number.isFinite(value) && value >= 0;
  const used = valid(pressure?.projectedTokens) ? pressure.projectedTokens : valid(pressure?.pressureTokens) ? pressure.pressureTokens : null;
  const capacity = valid(pressure?.contextWindow) && pressure.contextWindow > 0 ? pressure.contextWindow : null;
  const detailedKeys = ['system', 'tools', 'user', 'inject', 'skill', 'assistant', 'tool'];
  const detailed = detailedKeys.every(key => valid(composition?.[key]));
  const values = detailed ? detailedKeys.map(key => ({ key, value: composition[key] })) : [
    { key: 'system', value: breakdown?.systemTokens }, { key: 'tools', value: breakdown?.toolsTokens }, { key: 'messages', value: breakdown?.messageTokens },
  ].filter(item => valid(item.value));
  const total = values.reduce((sum, item) => sum + item.value, 0);
  const percent = used !== null && capacity !== null ? used / capacity * 100 : null;
  return { used, capacity, percent, fill: percent === null ? null : Math.min(100, Math.max(0, percent)), detailed,
    estimatedTotal: total,
    categories: values.filter(item => item.value > 0).map(item => ({ ...item, share: item.value / total * 100 })),
  };
}

function actorRecords(data) {
  const session = data.sessions.find(s => s.id === data.mainSession), context = data.context || {};
  const locate = event => {
    const t = session.turns.find(t => t.number === event.turn || t.id === event.turnId);
    const step = t?.steps.find(s => s.number === event.step || s.seq === event.seq);
    return { ...event, turn: event.turn ?? t?.number, step: event.step ?? step?.number, time: event.time ?? event.start ?? step?.start ?? t?.start };
  };
  const skills = (context.skillEvents || []).map((e, i) => ({ ...locate(e), id: e.id || 'skill:' + (e.seq ?? i) + ':' + i,
    name: e.name || e.path?.replace(/\\/g, '/').split('/').at(-2) || 'Skill',
  })).filter(e => Number.isFinite(e.time));
  const branches = context.agentBranches ? context.agentBranches.map(b => ({ ...b, steps: b.steps || [], reports: b.reports || [] })) :
    (context.collaborationEvents || []).filter(e => e.tool === 'spawn_agent').map((e, i) => {
      const events = context.collaborationEvents.filter(x => x.taskName === e.taskName && x.start >= e.start);
      const location = locate(e);
      return { id: e.taskPath || 'agent:' + i, name: e.taskName || '子代理', title: e.taskName || '子任务', start: e.start, end: null, returnTime: null,
        turn: location.turn, step: location.step, seq: e.seq, status: 'unknown', steps: [], reports: [], communications: events, source: e.source };
    });
  return { skills, branches };
}

// Only observations are grouped. A catalog is never converted into a skill load.
function skillObjects(events) {
  const objects = new Map();
  for (const event of events) {
    const entries = event.kind === 'catalog' ? event.entries || [] : [{ name: event.name, path: event.path }];
    for (const entry of entries) {
      const id = entry.name || entry.path;
      if (!id) continue;
      if (!objects.has(id)) objects.set(id, { id, name: entry.name || entry.path, description: entry.description, events: [] });
      objects.get(id).events.push(event);
    }
  }
  return [...objects.values()];
}

// Intervals use recorded execution/return times only. Unknown work is a point.
function agentExtent(branch) {
  return { start: branch.start, end: branch.returnTime ?? branch.end ?? branch.start, hasEnd: branch.returnTime != null || branch.end != null };
}

function visibleAgentBranches(branches, selected, limit = 3) {
  const rows = branches.slice(0, limit), picked = branches.find(b => b.id === selected);
  if (picked && !rows.some(b => b.id === picked.id)) rows[rows.length - 1] = picked;
  return { rows, hidden: branches.length - rows.length };
}

function skillUseEvents(skill) {
  return skill.events.filter(e => e.kind !== 'catalog' && e.status !== 'error' && e.status !== 'unknown');
}
function skillEvidenceLabel(event) {
  return event.kind === 'catalog' ? '出现在可用目录' : event.kind === 'skill-tool-load' ? '读入技能正文' : event.kind === 'skill-file-read' ? '读取技能材料' : '显式引用';
}

// The action view keeps the parent's ordered step axis. Child results use their
// own timestamps, never their step numbers as parent-step indexes.
function actorTimePosition(steps, x, time) {
  if (!steps.length) return 0;
  if (time <= steps[0].start) return x(0);
  for (let i = 1; i < steps.length; i++) {
    if (time < steps[i].start) {
      const fraction = (time - steps[i - 1].start) / Math.max(1, steps[i].start - steps[i - 1].start);
      return x(i - 1) + (x(i) - x(i - 1)) * fraction;
    }
  }
  const last = steps.length - 1, half = last ? (x(last) - x(last - 1)) / 2 : 56;
  return x(last) + half * Math.max(0, Math.min(1, (time - steps[last].start) / Math.max(1, steps[last].end - steps[last].start)));
}

function agentShowsResults(branch, span, actionView = false) {
  return Boolean(branch.results?.length && (actionView || span >= 128));
}

// Forks and ordinary result twigs occupy one plot. Dense fork groups remain
// selectable; an unobserved child ending never becomes an execution interval.
function layoutAgentForks(items, { left, right, measure, labelOf, expanded = null, slots = [-60, 60, -96, 96], compact = false, obstacles = [] }) {
  let groups = [...items].sort((a, b) => a.x - b.x).map(item => [item]);
  const hit = (a, b) => a.left < b.right + 10 && a.right + 10 > b.left && a.top < b.bottom + 8 && a.bottom + 8 > b.top;
  for (;;) {
    const placed = []; let failed = -1;
    for (const [index, members] of groups.entries()) {
      const single = members.length === 1, item = members[0], open = single && (item.showResults ?? item.branch.id === expanded);
      const x = item.x, end = single ? Math.max(x + 18, item.end) : x + 22;
      const label = labelOf(members), width = Math.min(right - left, measure(label) + 20);
      const cx = Math.max(left + width / 2, Math.min(right - width / 2, (x + end) / 2));
      const rect = { left: Math.min(x, cx - width / 2), right: Math.max(end, cx + width / 2) };
      const slot = slots.map(dy => ({ ...rect, x, end, cx, dy, label, members, open,
        top: dy - (compact ? 16 : open && dy < 0 ? 112 : 30), bottom: dy + (compact ? 4 : open ? (dy > 0 ? 108 : 35) : 10) }))
        .find(p => placed.every(q => !hit(p, q)) && obstacles.every(o => !hit(p, o)));
      if (!slot) { failed = index; break; }
      placed.push(slot);
    }
    if (failed < 0) return placed;
    const i = Math.max(0, failed - 1);
    groups.splice(i, 2, [...groups[i], ...groups[i + 1]]);
  }
}

  // A single inspector: action and observed result first, evidence on demand.
