        (fact.preview ? '<button class="geist-diff-action" data-insight-change="' + fact.seq + '">' + (fact.tone === 'bad' || fact.tone === 'unknown' ? '查看原计划' : '查看差异') + ' <span aria-hidden="true">↗</span></button>' : '') + '</article>';
